namespace Quantum.ErrorCorrection {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Diagnostics;
    open Microsoft.Quantum.Measurement;

    // Encode a qubit in the 3-qubit bit flip code
    operation EncodeBitFlip(logical : Qubit, physical : Qubit[]) : Unit {
        // |ψ⟩ = α|0⟩ + β|1⟩ → α|000⟩ + β|111⟩
        CNOT(logical, physical[0]);
        CNOT(logical, physical[1]);
    }

    // Measure syndrome for bit flip code
    operation MeasureSyndrome(physical : Qubit[]) : (Result, Result) {
        use ancilla = Qubit[2];

        // Syndrome 1: Z1*Z2 - measure if qubits 1 and 2 differ
        CNOT(physical[0], ancilla[0]);
        CNOT(physical[1], ancilla[0]);

        // Syndrome 2: Z2*Z3 - measure if qubits 2 and 3 differ
        CNOT(physical[1], ancilla[1]);
        CNOT(physical[2], ancilla[1]);

        let syn1 = MResetZ(ancilla[0]);
        let syn2 = MResetZ(ancilla[1]);

        return (syn1, syn2);
    }

    // Correct errors based on syndrome
    operation CorrectError(physical : Qubit[], syndrome : (Result, Result)) : Unit {
        let (s1, s2) = syndrome;

        // Syndrome table:
        // (0, 0): no error
        // (1, 0): error on qubit 1
        // (1, 1): error on qubit 2
        // (0, 1): error on qubit 3

        if (s1 == One and s2 == Zero) {
            X(physical[0]);
        } elif (s1 == One and s2 == One) {
            X(physical[1]);
        } elif (s1 == Zero and s2 == One) {
            X(physical[2]);
        }
    }

    @EntryPoint()
    operation BitFlipDemo() : Unit {
        use logical = Qubit();
        use physical = Qubit[3];

        // Prepare |+⟩ state
        H(logical);

        // Encode
        EncodeBitFlip(logical, physical);
        Reset(logical);

        // Introduce error on physical[1]
        X(physical[1]);
        Message("Introduced X error on qubit 2");

        // Measure syndrome
        let syndrome = MeasureSyndrome(physical);
        Message($"Syndrome: {syndrome}");

        // Correct
        CorrectError(physical, syndrome);
        Message("Error corrected!");
    }
}
